package au.com.endurancecoach;
import android.content.*;import android.view.*;import android.widget.*;import au.com.endurancecoach.core.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={28,35},qualifiers="w320dp-h640dp-xhdpi")
public class RoutePlannerUiTest {
 private Context context;
 @Before public void seed()throws Exception{context=RuntimeEnvironment.getApplication();context.getSharedPreferences("route-services",0).edit().putBoolean("enabled",false).commit();try(LocalStore s=new LocalStore(context)){s.put("snapshot",new JSONObject().put("events",new JSONArray().put(new JSONObject().put("event_id","e").put("active",true).put("name","Synthetic route-planner test event"))).put("plan",new JSONArray().put(session())));}}
 private JSONObject session()throws Exception{return new JSONObject().put("workout_id","route-session").put("revision",1).put("event_id","e").put("date",java.time.LocalDate.now(PlanEngine.ZONE).plusDays(1).toString()).put("type","run").put("title","Easy run").put("duration_min",60).put("intensity","Easy").put("status","scheduled");}
 private Intent intent(){return new Intent(context,RoutePlannerActivity.class).putExtra("workout_id","route-session");}
 @Test public void plannerHasThreeSectionsAndDoesNotAssumeAStart()throws Exception{try(ActivityController<RoutePlannerActivity> c=Robolectric.buildActivity(RoutePlannerActivity.class,intent()).create()){View root=c.get().getWindow().getDecorView();assertNotNull(text(root,"Suggested"));assertNotNull(text(root,"My routes"));assertNotNull(text(root,"Create"));assertNotNull(text(root,"Choose a starting point"));assertNotNull(text(root,"Import GPX"));}}
 @Test public void sessionDetailsOpenPlannerAndShowPinnedAttachment()throws Exception{try(ActivityController<MainActivity> c=Robolectric.buildActivity(MainActivity.class).create()){View root=c.get().getWindow().getDecorView();assertNotNull("The upcoming workout must appear on Today",text(root,"Workout details"));text(root,"Workout details").performClick();android.app.AlertDialog d=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(text(d.getWindow().getDecorView(),"Route planner"));text(d.getWindow().getDecorView(),"Route planner").performClick();assertEquals(RoutePlannerActivity.class.getName(),Shadows.shadowOf(c.get()).getNextStartedActivity().getComponent().getClassName());}}
 @Test public void savedRouteAndDraftRemainAvailableWithPublicServicesDisabled()throws Exception{try(CoachRepository r=new CoachRepository(context)){RouteStore routes=new RouteStore(context,r.store);JSONObject route=RoutePlan.create("Offline park","imported",new JSONArray("[[-31.95,115.85],[-31.949,115.85]]"),new JSONArray(),"GPX","");routes.save(route,null);routes.draft("route-session",new JSONObject().put("requirements",RouteMatcher.defaults(session(),new JSONArray()).put("start",new JSONArray("[-31.95,115.85]"))).put("waypoints",new JSONArray("[[-31.95,115.85]]")));}
  try(ActivityController<RoutePlannerActivity> c=Robolectric.buildActivity(RoutePlannerActivity.class,intent()).create()){View root=c.get().getWindow().getDecorView();text(root,"My routes").performClick();assertNotNull(text(root,"Offline park"));assertNull(text(root,"Choose a starting point"));}}
 @Test public void attachmentPinsCopyAndPreferencesAreSessionSpecific()throws Exception{try(CoachRepository r=new CoachRepository(context)){RouteStore routes=new RouteStore(context,r.store);JSONObject original=RoutePlan.create("Original","imported",new JSONArray("[[-31.95,115.85],[-31.949,115.85]]"),new JSONArray(),"GPX","");JSONObject req=RouteMatcher.defaults(session(),new JSONArray());routes.attach(session(),original,req);original.put("name","Changed");assertEquals("Original",routes.attachment("route-session").getJSONObject("route").getString("name"));assertNotNull(routes.preference(RouteMatcher.sessionKey(session())));assertNull(routes.preference("other_type"));assertEquals(2,r.store.pending("route").length());}}
 private TextView text(View v,String value){if(v instanceof TextView&&((TextView)v).getText().toString().equals(value))return (TextView)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){TextView result=text(((ViewGroup)v).getChildAt(i),value);if(result!=null)return result;}return null;}
}
